/* ============================================================
   UI primitives
   ============================================================ */
function Field({ label, children }) {
  return (
    <label className="field">
      <span>{label}</span>
      {children}
    </label>
  );
}
function Panel({ title, sub, action, children }) {
  return (
    <section className="panel">
      <div className="panel-h">
        <div>
          <h2 className="panel-title">{title}</h2>
          {sub && <p className="panel-sub">{sub}</p>}
        </div>
        {action}
      </div>
      {children}
    </section>
  );
}
function AddBtn({ onClick, children }) {
  return (
    <button className="add" onClick={onClick} type="button">
      + {children}
    </button>
  );
}
function RemoveBtn({ onClick, title = "Remove" }) {
  return (
    <button className="remove" onClick={onClick} title={title} type="button" aria-label={title}>
      ×
    </button>
  );
}

/* ============================================================
   App
   ============================================================ */
function Callboard({ auth, onLogout }) {
  const isSuperAdmin = auth.scope === "admin";                 // TCG employee — every show
  const isAccount = auth.scope === "admin" || auth.scope === "account"; // any signed-in account
  const initCrew = auth.scope === "show" && (auth.level || "crew") === "crew";
  const [showAccessOpen, setShowAccessOpen] = useState(false);
  const [pnlDashOpen, setPnlDashOpen] = useState(false);
  const [pnlDashBusy, setPnlDashBusy] = useState(false);
  const [pnlDashRows, setPnlDashRows] = useState([]);
  const [pnlBasis, setPnlBasis] = useState("est");
  const [navOpen, setNavOpen] = useState(false); // section switcher dropdown
  const [ready, setReady] = useState(false);
  const [atLanding, setAtLanding] = useState(false);
  /* Which admin screen is showing. This used to be one boolean per screen, and
     three separate places had to enumerate them: this state, the derivation
     below, and the landing guard. Adding To Do and Crew Roster without touching
     all three is exactly what broke them — the sidebar lit up and nothing
     happened. One value cannot fall out of step with itself. */
  // Land on Today rather than the calendar: the first question of the day is
  // "what needs me", not "what month is it".
  const [admSec, setAdmSec] = useState("today");
  const [events, setEvents] = useState([]); // summaries
  const [currentId, setCurrentId] = useState(null);
  const [event, setEvent] = useState(null);
  const showRole = event && event._role ? event._role : null;
  const level = isSuperAdmin ? "admin"
    : auth.scope === "account" ? ((showRole === "producer" || showRole === "tcg") ? "admin" : showRole === "dept_editor" ? "editor" : "crew")
    : (auth.level || "crew");
  const isShowAdmin = level === "admin";
  const isEditor = level === "editor";
  const canEditTabs = isShowAdmin || isEditor;
  const levelLabel = isSuperAdmin ? "Admin · all shows" : isShowAdmin ? "Show admin" : isEditor ? "Editor" : "Crew";
  const myDepts = (event && Array.isArray(event._depts)) ? event._depts : [];
  const effDeptOf = (lockKey) => { const td = (event && event.tabDepts) || {}; return Object.prototype.hasOwnProperty.call(td, lockKey) ? (td[lockKey] || "") : (DEFAULT_TAB_DEPTS[lockKey] || ""); };
  const deptCanEdit = (lockKey) => isEditor && myDepts.includes(effDeptOf(lockKey));
  const tabCanEdit = (lockKey) => isShowAdmin || deptCanEdit(lockKey) || !!(event && event[lockKey]);
  const [peopleOpen, setPeopleOpen] = useState(false);
  /* The sidebar badge, and the nudge on sign-in. Counted once when an admin
     signs in rather than polled: the number only has to be roughly right to do
     its job, and a poll on every admin page would cost a request a minute for
     a number that changes twice a day. Opening To Do reloads it properly. */
  const [taskCount, setTaskCount] = useState(0);
  const [taskNudge, setTaskNudge] = useState(null);
  const [agentOpen, setAgentOpen] = useState(false);
  useEffect(() => {
    if (!isSuperAdmin) return;
    let live = true;
    listTasks("open")
      .then((r) => {
        if (!live) return;
        const rows = r.tasks || [];
        const review = rows.filter((t) => t.review).length;
        const late = rows.filter((t) => !t.review && t.due && r.today && t.due < r.today).length;
        setTaskCount(rows.length);
        // Only interrupt when there is something genuinely waiting. A nudge
        // that appears every single sign-in stops being read within a week.
        if (review > 0 || late > 0) setTaskNudge({ review, late });
      })
      .catch(() => {});
    return () => { live = false; };
  }, [isSuperAdmin]);
  const [pendingInvoice, setPendingInvoice] = useState(null);
  const [tab, setTab] = useState(initCrew ? "mycall" : "home");
  const [status, setStatus] = useState("idle"); // idle | saving | saved | error
  const [toast, setToast] = useState("");
  const [loadError, setLoadError] = useState("");
  const loadingRef = useRef(false);
  const saveTimer = useRef(null);
  const undoStack = useRef([]);
  const redoStack = useRef([]);
  const lastSnap = useRef(0);
  const eventRef = useRef(null);
  const [histVer, setHistVer] = useState(0);
  const statusTimer = useRef(null);

  /* initial load — admin lists every show; crew get only their unlocked show */
  useEffect(() => {
    (async () => {
      try {
        if (isAccount) {
          let list = await listEvents();
          if (!list.length && isSuperAdmin) {
            const seed = seedEvent();
            const created = await createEvent({
              name: seed.name, client: seed.client, startDate: seed.startDate, endDate: seed.endDate, data: seed,
            });
            list = [created];
          }
          setEvents(list);
          setAtLanding(true);
        } else {
          const id = auth.showId;
          const ev = normalize(await getEvent(id));
          loadingRef.current = true;
          setEvents([{ id, name: ev.name, client: ev.client, startDate: ev.startDate, endDate: ev.endDate }]);
          setCurrentId(id);
          setEvent(ev);
        }
        setReady(true);
      } catch (e) {
        setLoadError(e.message || "Could not load. Try signing in again.");
        setReady(true);
      }
    })();
  }, []);

  /* autosave current event (debounced) → PATCH the show via our API */
  useEffect(() => {
    if (!event) return;
    if (loadingRef.current) {
      loadingRef.current = false;
      return;
    }
    setStatus("saving");
    clearTimeout(saveTimer.current);
    saveTimer.current = setTimeout(async () => {
      try {
        await updateEvent(event.id, {
          data: event, name: event.name, client: event.client, startDate: event.startDate, endDate: event.endDate,
        });
        setEvents((prev) =>
          prev.map((e) =>
            e.id === event.id
              ? { ...e, name: event.name, client: event.client, startDate: event.startDate, endDate: event.endDate }
              : e
          )
        );
        setStatus("saved");
        clearTimeout(statusTimer.current);
        statusTimer.current = setTimeout(() => setStatus("idle"), 1400);
      } catch (e) {
        setStatus("error");
      }
    }, 900);
    return () => clearTimeout(saveTimer.current);
  }, [event]);

  useEffect(() => { setNavOpen(false); }, [tab]);
  useEffect(() => { eventRef.current = event; }, [event]);
  useEffect(() => { undoStack.current = []; redoStack.current = []; lastSnap.current = 0; setHistVer((v) => v + 1); }, [currentId]);

  function summary(e) {
    return { id: e.id, name: e.name, client: e.client, startDate: e.startDate, endDate: e.endDate };
  }

  const update = (fn) => {
    const cur = eventRef.current;
    if (cur) {
      const now = Date.now();
      if (now - lastSnap.current > 700) {
        undoStack.current.push(cur);
        if (undoStack.current.length > 40) undoStack.current.shift();
        redoStack.current = [];
        lastSnap.current = now;
        setHistVer((v) => v + 1);
      }
    }
    setEvent((prev) => {
      const e = clone(prev);
      fn(e);
      return e;
    });
  };
  const undo = () => {
    if (!undoStack.current.length) return;
    const prevState = undoStack.current.pop();
    if (eventRef.current) redoStack.current.push(eventRef.current);
    lastSnap.current = 0;
    setEvent(prevState);
    setHistVer((v) => v + 1);
  };
  const redo = () => {
    if (!redoStack.current.length) return;
    const nextState = redoStack.current.pop();
    if (eventRef.current) undoStack.current.push(eventRef.current);
    lastSnap.current = 0;
    setEvent(nextState);
    setHistVer((v) => v + 1);
  };
  useEffect(() => {
    const onKey = (e) => {
      const t = e.target;
      const editable = t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT" || t.isContentEditable);
      const mod = e.metaKey || e.ctrlKey;
      if (mod && (e.key === "z" || e.key === "Z") && !editable) { e.preventDefault(); if (e.shiftKey) redo(); else undo(); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const flash = (msg) => {
    setToast(msg);
    setTimeout(() => setToast(""), 1900);
  };

  async function switchEvent(id, targetTab) {
    if (id === currentId) { setTab(targetTab || "home"); return; }
    try {
      const e = normalize(await getEvent(id));
      loadingRef.current = true;
      setCurrentId(id);
      setEvent(e);
      setTab(targetTab || "home");
    } catch (err) {
      flash(err.message || "Couldn't open that show");
    }
  }
  /* Opening a show from a list.

     The landing guard renders the admin shell when EITHER atLanding is true OR
     an admin section is open. Clearing only atLanding therefore did nothing
     visible: the section was still set, the guard still matched, and the screen
     you clicked from stayed put. goAdmin("shows") resets it, so the show can
     actually come forward.

     This was already broken for "Open show" on the Pipeline and inside a quote —
     same helper, same missing step. Fixing it here fixes those too.

     Billing also passes a tab and an invoice, because a row in the Billing queue
     IS an invoice: landing on the tile grid and making you find Billing again is
     two clicks back to where you already were. Everything else still lands on
     the tiles. (goAdmin is declared below; this only ever runs from a click, by
     which point it is initialised.) */
  const openLandingShow = (id, targetTab, invoiceId) => {
    goAdmin("shows");
    setAtLanding(false);
    setPendingInvoice(invoiceId || null);
    switchEvent(id, targetTab);
  };

  async function newEvent() {
    const name = window.prompt("Name this show:", "New Event");
    if (name === null) return;
    const pw = window.prompt(
      "Set a password for this show (crew use it to open the show).\nLeave blank for no password:",
      ""
    );
    try {
      const e = blankEvent();
      e.name = name || "New Event";
      const created = await createEvent({
        name: e.name, client: e.client, startDate: e.startDate, endDate: e.endDate, data: e, password: pw || "",
      });
      e.id = created.id;
      setEvents((prev) => [...prev, created]);
      loadingRef.current = true;
      setCurrentId(e.id);
      setEvent(e);
      setTab("home");
      flash(pw ? "Show created with password" : "Show created");
    } catch (err) {
      flash(err.message || "Couldn't create show");
    }
  }

  async function newDemoEvent() {
    try {
      const e = demoEvent();
      const created = await createEvent({ name: e.name, client: e.client, startDate: e.startDate, endDate: e.endDate, data: e, password: "" });
      e.id = created.id;
      setEvents((prev) => [...prev, created]);
      loadingRef.current = true;
      setCurrentId(e.id);
      setEvent(e);
      setTab("home");
      flash("Demo event created — explore or delete it anytime");
    } catch (err) {
      flash(err.message || "Couldn't create demo");
    }
  }

  async function openPnlDashboard() {
    setPnlDashOpen(true); setPnlDashBusy(true); setPnlDashRows([]);

    /* Two bulk reads before the loop, not two more requests per show.

       The costing one is the fix for a real bug: this roll-up called
       computePnl(full) on the show record alone, and the figures have lived in
       `show_costing` since they were moved out of reach of crew tokens. Every
       field it wanted was undefined, so every show reported zero. */
    let costingById = {}, receiptsByShow = {};
    try { costingById = (await getAllCosting()).costing || {}; } catch (e) {}
    try {
      ((await listShowExpenseTotals()).rows || []).forEach((r) => {
        if (!r || !r.show_id) return;
        (receiptsByShow[r.show_id] = receiptsByShow[r.show_id] || []).push(r);
      });
    } catch (e) {}

    const rows = [];
    for (const ev of events) {
      try {
        const full = normalize(await getEvent(ev.id));
        /* Costing LAST: it is the authoritative source for every figure it
           carries, and a show record still holding pre-move leftovers must not
           win over what the Costing tab has actually saved. */
        const merged = { ...full, ...(costingById[ev.id] || {}) };
        rows.push({
          id: ev.id, name: full.name || ev.name || "Untitled",
          client: full.client || "", startDate: full.startDate || "",
          ...computePnl(merged, receiptsByShow[ev.id]),
        });
      } catch (e) {}
    }
    rows.sort((a, b) => (b.startDate || "").localeCompare(a.startDate || ""));
    setPnlDashRows(rows); setPnlDashBusy(false);
  }
  async function duplicateEvent() {
    if (!event) return;
    const e = clone(event);
    e.name = event.name + " (copy)";
    /* The server omits `time` for a role that may not see it. Duplicating is
       an admin action so this should always be present — but a missing key
       here would be a blank screen rather than a missing figure. */
    e.time = { days: ((event.time && event.time.days) || []).map((d) => ({ ...d })), entries: {} };
    e.records = [];
    e.diagrams = (e.diagrams || []).map((d) => ({ ...d, id: uid() }));
    try {
      const created = await createEvent({
        name: e.name, client: e.client, startDate: e.startDate, endDate: e.endDate, data: e, password: "",
      });
      e.id = created.id;
      setEvents((prev) => [...prev, created]);
      loadingRef.current = true;
      setCurrentId(e.id);
      setEvent(e);
      setTab("home");
      flash("Duplicated — set its password under Show access");
    } catch (err) {
      flash(err.message || "Couldn't duplicate");
    }
  }

  /* Deleting a show, by id, with no confirmation of its own.
     It used to be a button in the top bar with a browser confirm on it, one
     along from Duplicate and Show access — and a browser confirm is not a
     safeguard, it is a reflex. The decision now happens in Settings >
     Delete a show, where the show has to be found and its name typed out.
     This function is only the doing. */
  async function removeShow(id) {
    if (!id) return;
    /* Deliberately NOT caught. The screen that calls this shows the reason to
       whoever pressed the button; swallowing it here and flashing a toast was
       fine for a top-bar button and is not fine for a typed confirmation that
       has to be able to say "that did not work, and here is why". */
    await deleteEvent_api(id);
    const next = events.filter((e) => e.id !== id);
    setEvents(next);

    /* ONLY MOVE IF THE DELETED SHOW WAS THE ONE OPEN.
       The old version always jumped to the first show in the list, which was
       right when the only way to delete was from the show you were looking
       at. From Settings it would throw away whatever was open for no reason —
       delete a leftover import and find yourself in a different job. */
    if (id !== currentId) return;

    if (next.length) {
      const e = normalize(await getEvent(next[0].id));
      loadingRef.current = true;
      setCurrentId(next[0].id);
      setEvent(e);
    } else {
      const seed = blankEvent();
      const created = await createEvent({
        name: seed.name, client: seed.client, startDate: seed.startDate, endDate: seed.endDate, data: seed, password: "",
      });
      seed.id = created.id;
      loadingRef.current = true;
      setEvents([created]);
      setCurrentId(seed.id);
      setEvent(seed);
    }
    setTab("home");
  }

  async function changeShowPassword() {
    const pw = window.prompt(
      "Set a new password for this show.\nLeave blank to remove password protection:",
      ""
    );
    if (pw === null) return;
    try {
      await dbSetPassword(currentId, pw);
      setEvents((prev) => prev.map((e) => (e.id === currentId ? { ...e, hasPassword: !!pw } : e)));
      flash(pw ? "Password updated" : "Password removed");
    } catch (err) {
      flash(err.message || "Couldn't update password");
    }
  }

  function copyBrief() {
    const t = briefText(event);
    try {
      navigator.clipboard.writeText(t);
      flash("Brief copied — paste it to your crew");
    } catch {
      flash("Copy failed on this device");
    }
  }

  if (!ready)
    return (
      <div className="cb">
        <style>{CSS}</style>
        <div className="loading">Loading the callboard…</div>
      </div>
    );
  // Nobody but a TCG admin ever sees a section, whatever the state says.
  const admSection = isSuperAdmin ? admSec : "shows";
  const goAdmin = (s) => setAdmSec(s || "shows");
  const goAdminFromShow = (s) => { goAdmin(s); setAtLanding(true); };
  const calendar = (
    <ShowsCalendar
      events={events}
      isAdmin={isSuperAdmin}
      hasSidebar={isSuperAdmin}
      onOpen={openLandingShow}
      onNew={newEvent}
      onDemo={newDemoEvent}
      onPipeline={() => goAdmin("pipeline")}
      onPeople={() => setPeopleOpen(true)}
      onCatalog={() => goAdmin("catalog")}
      onQuotes={() => goAdmin("quotes")}
      onLogout={onLogout}
    />
  );

  if (atLanding || (isSuperAdmin && admSection !== "shows"))
    return (
      <div className="cb">
        <style>{CSS}</style>
        {peopleOpen && <PeopleAccess events={events} onClose={() => setPeopleOpen(false)} />}
      {isSuperAdmin && !agentOpen && (
        <button className="ag-fab" onClick={() => setAgentOpen(true)} title="Ask the assistant">Ask</button>
      )}
      {agentOpen && <AgentPanel onClose={() => setAgentOpen(false)} />}

      {taskNudge && (
        <div className="tk-nudge" role="status">
          <div className="tk-nudgebody">
            <b>
              {taskNudge.review > 0 && (taskNudge.review + " thing" + (taskNudge.review === 1 ? "" : "s") + " came in")}
              {taskNudge.review > 0 && taskNudge.late > 0 && " · "}
              {taskNudge.late > 0 && (taskNudge.late + " overdue")}
            </b>
            <span>on your to-do list.</span>
          </div>
          <button className="btn" onClick={() => { setTaskNudge(null); goAdmin("todo"); setAtLanding(true); }}>Open</button>
          <button className="tk-nudgex" onClick={() => setTaskNudge(null)} title="Dismiss">×</button>
        </div>
      )}
        <div className="adm-shell">
          {isSuperAdmin ? (
            <AdminSidebar active={admSection} go={goAdmin} onPeople={() => setPeopleOpen(true)} onLogout={onLogout} taskCount={taskCount} />
          ) : null}
          <div className="adm-main">
            {admSection === "today" ? (
              <TodayScreen go={goAdmin} onOpenShow={openLandingShow} />
            ) : admSection === "todo" ? (
              <TasksScreen onClose={() => goAdmin("shows")} onOpenShow={openLandingShow} />
            ) : admSection === "pipeline" ? (
              <PipelineBoard onClose={() => goAdmin("shows")} onOpenShow={openLandingShow} />
            ) : admSection === "catalog" ? (
              <CatalogScreen onClose={() => goAdmin("shows")} />
            ) : admSection === "quotes" ? (
              <QuotesScreen
                onClose={() => goAdmin("shows")}
                onOpenShow={openLandingShow}
                onShowCreated={(created) => setEvents((prev) => prev.concat([created]))}
              />
            ) : admSection === "billing" ? (
              <BillingScreen onClose={() => goAdmin("shows")} onOpenShow={openLandingShow} />
            ) : admSection === "expenses" ? (
              <ExpensesScreen onClose={() => goAdmin("shows")} events={events} />
            ) : admSection === "reports" ? (
              <ReportsScreen onClose={() => goAdmin("shows")} />
            ) : admSection === "roster" ? (
              <RosterScreen onClose={() => goAdmin("shows")} />
            ) : admSection === "staff" ? (
              <TcgStaffScreen onClose={() => goAdmin("shows")} />
            ) : admSection === "settings" ? (
              <SettingsScreen onClose={() => goAdmin("shows")}
                              shows={events} currentId={currentId} onDeleteShow={removeShow} />
            ) : (
              calendar
            )}
          </div>
        </div>
      </div>
    );

  if (loadError || !event)
    return (
      <div className="cb">
        <style>{CSS}</style>
        <div className="loading">
          {loadError || "No show loaded."}
          <div style={{ marginTop: 16 }}>
            <button className="btn" onClick={onLogout}>Back to sign in</button>
          </div>
        </div>
      </div>
    );

  const dateRange =
    event.startDate && event.endDate ? `${prettyDate(event.startDate)} – ${prettyDate(event.endDate)}` : "Dates TBD";

  return (
    <div className="cb">
      <style>{CSS}</style>

      <div className="adm-shell">
        {isSuperAdmin ? (
          /* A show sits underneath Shows, so that stays lit while you're in one. */
          <AdminSidebar active="shows" go={goAdminFromShow} onPeople={() => setPeopleOpen(true)} onLogout={onLogout} taskCount={taskCount} />
        ) : null}
        <div className="adm-main">

      {/* top control bar */}
      <div className="topbar">
        <div className="brand">
          <span className="brand-tab">CREW</span>
          <span className="brand-rest">CALL</span>
        </div>
        {isSuperAdmin ? (
          <>
            <div className="evt-picker">
              <select value={currentId || ""} onChange={(e) => switchEvent(e.target.value)}>
                {events.map((e) => (
                  <option key={e.id} value={e.id}>
                    {(e.hasPassword ? "🔒 " : "") + (e.name || "Untitled event")}
                  </option>
                ))}
              </select>
            </div>
            <div className="top-actions">
              <button className="btn ghost" onClick={() => setAtLanding(true)}>Calendar</button>
              <button className="btn" onClick={newEvent}>+ New</button>
              <button className="btn ghost" onClick={newDemoEvent} title="Create a fully populated fictional event for demos">Demo</button>
              <button className="btn ghost" onClick={duplicateEvent}>Duplicate</button>
              <button className="btn ghost" onClick={() => setShowAccessOpen(true)}>Show access</button>
              {isSuperAdmin && <button className="btn ghost" onClick={openPnlDashboard}>P&amp;L Dashboard</button>}
              {/* DELETE IS NOT UP HERE ANY MORE.
                  It sat one button along from Duplicate and Show access, both
                  of which are pressed often, and a mis-hit removed a show for
                  everyone with nothing but a browser confirm in the way. It
                  now lives in Settings > Delete a show, where getting to it is
                  a decision rather than a slip, and where the show has to be
                  named by hand before anything happens. */}
            </div>
          </>
        ) : (
          <div className="evt-picker locked">
            <span className="lock-name">{event ? event.name : ""}</span>
          </div>
        )}
        <div className="top-right">
          {event && <button className="btn ghost undo-btn" onClick={undo} disabled={!undoStack.current.length} title="Undo (⌘Z)">↶</button>}
          {event && <button className="btn ghost undo-btn" onClick={redo} disabled={!redoStack.current.length} title="Redo (⌘⇧Z)">↷</button>}
          <div className={"savechip " + status}>
            {status === "saving"
              ? "Saving…"
              : status === "saved"
              ? "Saved ✓"
              : status === "error"
              ? "Save failed"
              : levelLabel}
          </div>
          <button className="btn ghost signout" onClick={onLogout} title="Sign out">Sign out</button>
        </div>
      </div>

      {/* body: the home board, or a single section page */}
      {tab === "home" ? (
        <HomeScreen event={event} update={update} go={setTab} copyBrief={copyBrief} dateRange={dateRange} isAdmin={isShowAdmin} isSuperAdmin={isSuperAdmin} canEdit={canEditTabs} flash={flash} />
      ) : (
        <>
          <div className="pagebar">
            <button className="backbtn" onClick={() => setTab("home")} title="Back to all sections">
              <span className="chev">‹</span> Home
            </button>
            <div className="pagebar-nav">
              <button className="pagebar-switch" onClick={() => setNavOpen((o) => !o)} aria-expanded={navOpen} title="Jump to another section">
                {SECTION_LABEL[tab] || "Section"} <span className="pagebar-caret">▾</span>
              </button>
              {navOpen && (
                <>
                  <div className="pagebar-backdrop" onClick={() => setNavOpen(false)} />
                  <div className="pagebar-menu">
                    <button className="pagebar-menu-item home" onClick={() => setTab("home")}>⌂ All sections</button>
                    {SECTIONS.filter((sec) => (!sec.adminOnly || isShowAdmin) && (!sec.superOnly || isSuperAdmin) && (!sec.editorOnly || canEditTabs)).map((sec) => (
                      <button key={sec.key} className={"pagebar-menu-item" + (sec.key === tab ? " on" : "")} onClick={() => setTab(sec.key)}>
                        <span className="pagebar-menu-dot" style={{ background: sec.color }} />{sec.label}
                      </button>
                    ))}
                  </div>
                </>
              )}
            </div>
            <button className="print-btn" onClick={() => window.print()} title="Print or save as PDF">
              🖨️ Print / PDF
            </button>
          </div>
          <main className={"content" + (tab === "rundown" ? " content-wide" : "")} data-show={event.name} data-tab={SECTION_LABEL[tab] || tab}>
            {tab === "mycall" && <MyCallTab event={event} showId={currentId} update={update} />}
            {tab === "brief" && <LockWrapper canEdit={tabCanEdit("briefUnlocked")} label="Brief"><BriefTab event={event} update={update} isAdmin={isShowAdmin} isTcg={isSuperAdmin} showId={currentId} /></LockWrapper>}
            {tab === "schedule" && <ScheduleTab event={event} update={update} isAdmin={isShowAdmin} editor={deptCanEdit("scheduleUnlocked")} showId={currentId} />}
            {tab === "rundown" && <RundownTab event={event} update={update} isAdmin={isShowAdmin} editor={deptCanEdit("rundownUnlocked")} myDepts={myDepts} showId={currentId} />}
            {tab === "todos" && <TodoTab event={event} update={update} isAdmin={isShowAdmin} editor={deptCanEdit("todosUnlocked")} />}
            {tab === "documents" && <LockWrapper canEdit={tabCanEdit("documentsUnlocked")} label="Show Documents"><DocumentsTab event={event} update={update} /></LockWrapper>}
            {tab === "itinerary" && <LockWrapper canEdit={tabCanEdit("itineraryUnlocked")} label="Itinerary"><ItineraryTab event={event} update={update} /></LockWrapper>}
            {tab === "notes" && <NotesTab event={event} update={update} />}
            {tab === "audio" && <IOPage event={event} update={update} kind="audio" isAdmin={isShowAdmin} editor={deptCanEdit("audioUnlocked")} />}
            {tab === "video" && <IOPage event={event} update={update} kind="video" isAdmin={isShowAdmin} editor={deptCanEdit("videoUnlocked")} />}
            {tab === "comms" && <CommPatchTab event={event} update={update} isAdmin={isShowAdmin} editor={deptCanEdit("commsUnlocked")} />}
            {tab === "wifi" && <LockWrapper canEdit={tabCanEdit("wifiUnlocked")} label="Wi-Fi Info"><WifiTab event={event} update={update} /></LockWrapper>}
            {tab === "diagrams" && <LockWrapper canEdit={tabCanEdit("diagramsUnlocked")} label="Diagrams"><DiagramsTab event={event} update={update} /></LockWrapper>}
            {tab === "floorplans" && <LockWrapper canEdit={tabCanEdit("floorplansUnlocked")} label="Floorplans"><FloorplansTab event={event} update={update} /></LockWrapper>}
            {tab === "pull" && <PullTab event={event} update={update} isAdmin={isShowAdmin} editor={deptCanEdit("gearEditUnlocked")} />}
            {tab === "records" && <LockWrapper canEdit={tabCanEdit("recordsUnlocked")} label="Records"><RecordsTab event={event} update={update} /></LockWrapper>}
            {tab === "hours" && isShowAdmin && <LockWrapper canEdit={tabCanEdit("hoursUnlocked")} label="Hours"><HoursTab event={event} update={update} /></LockWrapper>}
            {tab === "billing" && isShowAdmin && (
              <BillingTab
                event={event}
                showId={currentId}
                go={setTab}
                openInvoiceId={pendingInvoice}
                onInvoiceOpened={() => setPendingInvoice(null)}
              />
            )}
            {tab === "costing" && isShowAdmin && <CostingTab event={event} />}
            {tab === "survey" && isShowAdmin && <SurveyTab event={event} update={update} showId={currentId} />}
          </main>
        </>
      )}

        </div>
      </div>

      {peopleOpen && <PeopleAccess events={events} onClose={() => setPeopleOpen(false)} />}

      {pnlDashOpen && (
        <div className="pnl-dash-overlay" onClick={() => setPnlDashOpen(false)}>
          <div className="pnl-dash" onClick={(e) => e.stopPropagation()}>
            <div className="pnl-dash-head">
              <h2>P&amp;L — All Shows</h2>
              <button className="pnl-dash-x" onClick={() => setPnlDashOpen(false)}>✕</button>
            </div>
            {!pnlDashBusy && (
              <div className="pnl-dash-basis">
                <button className={"pnl-basis-chip" + (pnlBasis === "est" ? " on" : "")} onClick={() => setPnlBasis("est")}>Estimated</button>
                <button className={"pnl-basis-chip" + (pnlBasis === "act" ? " on" : "")} onClick={() => setPnlBasis("act")}>Actual</button>
              </div>
            )}
            {pnlDashBusy ? (
              <div className="pnl-dash-loading">Loading all shows…</div>
            ) : (
              (() => {
                const rows = pnlDashRows;
                const rev = (r) => (pnlBasis === "act" ? r.revAct : r.revEst);
                const cost = (r) => (pnlBasis === "act" ? r.costAct : r.costEst);
                const net = (r) => (pnlBasis === "act" ? r.netAct : r.netEst);
                const t = rows.reduce((a, r) => { a.rev += rev(r); a.cost += cost(r); a.net += net(r); a.unpaid += r.unpaid; return a; }, { rev: 0, cost: 0, net: 0, unpaid: 0 });
                const marg = (rv, nt) => (rv > 0 ? Math.round((nt / rv) * 100) + "%" : "–");
                return (
                  <div className="pnl-dash-body">
                    <div className="pnl-dash-cards">
                      <div className="pnl-dc"><span>Total revenue</span><b>{pnlMoney(t.rev)}</b></div>
                      <div className="pnl-dc"><span>Total cost</span><b>{pnlMoney(t.cost)}</b></div>
                      <div className="pnl-dc"><span>Net profit</span><b className={t.net < 0 ? "neg" : "pos"}>{pnlMoney(t.net)}</b></div>
                      <div className="pnl-dc"><span>Margin</span><b>{marg(t.rev, t.net)}</b></div>
                      <div className="pnl-dc"><span>Outstanding</span><b className={t.unpaid > 0 ? "amber" : ""}>{pnlMoney(t.unpaid)}</b></div>
                    </div>
                    <div className="pnl-dash-scroll">
                      <table className="pnl-dash-table">
                        <thead><tr><th>Show</th><th>Revenue</th><th>Cost</th><th>Net</th><th>Margin</th><th>Outstanding</th></tr></thead>
                        <tbody>
                          {rows.map((r) => (
                            <tr key={r.id}>
                              <td className="pnl-dash-name">{r.name}{r.startDate ? <em> · {prettyDate(r.startDate)}</em> : null}</td>
                              <td>{pnlMoney(rev(r))}</td>
                              <td>{pnlMoney(cost(r))}</td>
                              <td className={net(r) < 0 ? "neg" : "pos"}>{pnlMoney(net(r))}</td>
                              <td>{marg(rev(r), net(r))}</td>
                              <td className={r.unpaid > 0 ? "amber" : ""}>{r.unpaid > 0 ? pnlMoney(r.unpaid) : "–"}</td>
                            </tr>
                          ))}
                          {!rows.length && <tr><td colSpan={6} className="pnl-dash-empty">No shows found.</td></tr>}
                        </tbody>
                      </table>
                    </div>
                  </div>
                );
              })()
            )}
          </div>
        </div>
      )}

      {showAccessOpen && (
        <ShowAccessModal
          show={events.find((e) => e.id === currentId) || { name: event.name }}
          currentId={currentId}
          onClose={() => setShowAccessOpen(false)}
          onSaved={(flags) => {
            setEvents((prev) => prev.map((e) => (e.id === currentId ? { ...e, ...flags } : e)));
            flash("Show access updated");
          }}
        />
      )}

      {toast && <div className="toast">{toast}</div>}
    </div>
  );
}

/* ============================================================
   HOME BOARD — colored tiles that open each section
   ============================================================ */
const SECTIONS = [
  { key: "mycall", label: "My Call Sheet", desc: "Your call time, hotel & travel", color: "#00B4D8", group: "" },
  { key: "brief", label: "Brief", desc: "Venue, contacts, crew", color: "#F3B24A", group: "" },
  { key: "schedule", label: "Schedule", desc: "Daily run of show", color: "#7E93EC", group: "Show Documents" },
  { key: "rundown", label: "Run of Show", desc: "Live rundown & show clock", color: "#E8683D", group: "Show Documents" },
  { key: "todos", label: "To-Do", desc: "Tasks & assignments", color: "#E9C46A", group: "Show Documents" },
  { key: "itinerary", label: "Itinerary", desc: "Hotels & flights", color: "#46C5B8", group: "Show Documents" },
  { key: "notes", label: "Meals & Notes", desc: "Catering, pre-con notes", color: "#F0895C", group: "Show Documents" },
  { key: "floorplans", label: "Floorplans", desc: "Room floorplans & layouts", color: "#5FA8D3", group: "Show Documents" },
  { key: "documents", label: "Documents", desc: "Show flows & agendas", color: "#4EA8DE", group: "Show Documents" },
  { key: "video", label: "Video I/O", desc: "Video patch sheets", color: "#D97CC0", group: "Tech Documents" },
  { key: "audio", label: "Audio I/O", desc: "Audio patch sheets", color: "#9C9AA6", group: "Tech Documents" },
  { key: "diagrams", label: "Diagrams", desc: "Stage plots & rigging", color: "#EC6A63", group: "Tech Documents" },
  { key: "pull", label: "Pull List", desc: "Gear pull & load-out", color: "#8E7CC3", group: "Tech Documents" },
  { key: "comms", label: "Comm Patch", desc: "Intercom channels & assignments", color: "#4FB0A5", group: "Tech Documents" },
  { key: "wifi", label: "Wi-Fi Info", desc: "Networks, SSIDs & passwords", color: "#2E9BB5", group: "Tech Documents" },
  /* adminOnly, not editorOnly: isShowAdmin is a TCG admin or a producer. A
   department editor does not need everyone else's in and out times, and the
   server no longer sends them the timesheet at all. */
  { key: "hours", label: "Hours", desc: "Crew timesheet", color: "#6FD08A", adminOnly: true, group: "Admin" },
  { key: "survey", label: "Post-Show Survey", desc: "Crew feedback, kept with the show", color: "#C77DFF", adminOnly: true, group: "Admin" },
  { key: "billing", label: "Billing", desc: "Invoices, payments & what is owed", color: "#C9A227", adminOnly: true, group: "Admin" },
  { key: "costing", label: "P&L / Costing", desc: "Budget vs actual — admin only", color: "#2E9E7B", adminOnly: true, group: "Admin" },
];
const GROUP_ORDER = ["Show Documents", "Tech Documents", "Admin"];
const GROUP_META = { "Show Documents": "#5A7FE0", "Tech Documents": "#C77DA0", "Admin": "#3FA37B" };
const SECTION_LABEL = SECTIONS.reduce((m, s) => ((m[s.key] = s.label), m), {});

function TileIcon({ name }) {
  const p = { width: 30, height: 30, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 1.9, strokeLinecap: "round", strokeLinejoin: "round" };
  switch (name) {
    case "brief":
      return (<svg {...p}><rect x="5" y="4" width="14" height="17" rx="2" /><path d="M9 4h6v3H9z" /><path d="M8 11h8M8 15h8" /></svg>);
    case "schedule":
      return (<svg {...p}><rect x="4" y="5" width="16" height="16" rx="2" /><path d="M4 9h16M8 3v4M16 3v4" /></svg>);
    case "documents":
      return (<svg {...p}><rect x="5" y="3" width="14" height="18" rx="2" /><path d="M9 3v18M5 9h14M5 15h14" /></svg>);
    case "costing":
      return (<svg {...p}><path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" /></svg>);
    case "roster":
      return (<svg {...p}><circle cx="9" cy="7" r="4"/><path d="M2 21v-2a4 4 0 0 1 4-4h6a4 4 0 0 1 4 4v2"/><path d="M19 8v6M22 11h-6"/></svg>);
    case "itinerary":
      return (<svg {...p}><path d="M3 13l18-7-7 18-2.5-7.5L3 13z" /></svg>);
    case "notes":
      return (<svg {...p}><path d="M6 3v8a3 3 0 0 0 6 0V3M9 3v18" /><path d="M17 3c-1.5 1-2 3-2 5s.5 3 2 3v10" /></svg>);
    case "video":
      return (<svg {...p}><rect x="3" y="5" width="18" height="12" rx="2" /><path d="M8 21h8M12 17v4" /></svg>);
    case "audio":
      return (<svg {...p}><path d="M6 4v16M12 4v16M18 4v16" /><circle cx="6" cy="9" r="2" /><circle cx="12" cy="15" r="2" /><circle cx="18" cy="8" r="2" /></svg>);
    case "diagrams":
      return (<svg {...p}><path d="M4 19L14 4l6 15z" /><path d="M4 19h16" /></svg>);
    case "wifi":
      return (<svg {...p}><path d="M2.5 9a15 15 0 0 1 19 0" /><path d="M5.5 12.6a10 10 0 0 1 13 0" /><path d="M8.5 16.2a5.5 5.5 0 0 1 7 0" /><circle cx="12" cy="19.6" r=".9" fill="currentColor" stroke="none" /></svg>);
    case "billing":
      return (<svg {...p}><path d="M5 3h14v18l-3-2-2 2-2-2-2 2-2-2-3 2z" /><path d="M9 8h6M9 12h6M9 16h3" /></svg>);
    case "pull":
      return (<svg {...p}><rect x="4" y="7" width="16" height="13" rx="2" /><path d="M4 11h16M9 4h6l1 3H8z" /><path d="M9.5 15.5l1.5 1.5 3-3" /></svg>);
    case "records":
      return (<svg {...p}><rect x="5" y="3" width="14" height="18" rx="2" /><path d="M9 8h6M9 12h6M9 16h4" /></svg>);
    case "hours":
      return (<svg {...p}><circle cx="12" cy="12" r="8" /><path d="M12 8v4l3 2" /></svg>);
    case "floorplans":
      return (<svg {...p}><rect x="3" y="3" width="18" height="18" rx="1" /><path d="M3 9h18M9 3v18M14 9v12" /></svg>);
    case "folder":
      return (<svg {...p}><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" /></svg>);
    default:
      return null;
  }
}

function tileStat(key, event) {
  switch (key) {
    case "brief": return `${event.crew.length} crew`;
    case "schedule": return `${event.schedule.length} day${event.schedule.length === 1 ? "" : "s"}`;
    case "documents": return `${event.documents.length} doc${event.documents.length === 1 ? "" : "s"}`;
    case "itinerary": return `${event.itinerary.flights.length} flights · ${event.itinerary.stays.length} stays`;
    case "notes": return `${event.notes.length} notes · ${event.meals.length} meals`;
    case "video": return `${event.video.blocks.length} device${event.video.blocks.length === 1 ? "" : "s"}`;
    case "audio": return `${event.audio.blocks.length} device${event.audio.blocks.length === 1 ? "" : "s"}`;
    case "diagrams": return `${event.diagrams.length} file${event.diagrams.length === 1 ? "" : "s"}`;
    case "wifi": return `${(event.wifi || []).length} network${(event.wifi || []).length === 1 ? "" : "s"}`;
    case "floorplans": return `${(event.floorplans || []).length} file${(event.floorplans || []).length === 1 ? "" : "s"}`;
    case "pull": {
      const all = [...(event.pull?.cases || []).flatMap((c) => c.items), ...(event.pull?.loose || [])];
      const items = all.length;
      const out = all.filter((i) => i.out && !i.in).length;
      return out > 0 ? `${items} items · ${out} out` : `${items} item${items === 1 ? "" : "s"}`;
    }
    case "records": return `${event.records.length} record${event.records.length === 1 ? "" : "s"}`;
    case "hours": {
      /* Only ever rendered for a tile the viewer can see, and Hours is now
         admin-only — but the server omits `time` entirely below producer, and
         iterating undefined here would blank the whole home screen rather than
         one subtitle. */
      if (!event.time || !Array.isArray(event.time.days)) return "";
      let t = 0;
      for (const c of event.crew)
        for (const d of event.time.days) {
          const en = event.time.entries?.[c.id]?.[d.id];
          if (en) t += hoursBetween(en.in, en.out);
        }
      return `${fmtHrs(t)} hrs logged`;
    }
    case "rundown": { const n = (event.rundown && event.rundown.rows ? event.rundown.rows : []).filter((r) => r.kind === "item").length; return `${n} segment${n === 1 ? "" : "s"}`; }
    case "todos": { const open = (event.todos || []).filter((t) => !t.done).length; const over = (event.todos || []).filter(todoOverdue).length; return over > 0 ? `${open} open · ${over} overdue` : `${open} open`; }
    case "costing": return "Admin only";
    default: return "";
  }
}

